export interface RateSummary {
  falseAlarm: number;
  missedDetection: number;
}

function validRate(value: number): boolean {
  return Number.isFinite(value) && value >= 0 && value <= 1;
}

export class BinaryRateLedger {
  private entries: RateSummary[] = [];

  add(falseAlarm: number, missedDetection: number): void {
    if (!validRate(falseAlarm) || !validRate(missedDetection)) {
      throw new RangeError("rates must be finite values from 0 through 1");
    }
    this.entries.push({ falseAlarm, missedDetection });
  }

  average(): RateSummary | null {
    if (this.entries.length === 0) return null;
    let falseAlarm = 0;
    let missedDetection = 0;
    for (const entry of this.entries) {
      falseAlarm += entry.falseAlarm;
      missedDetection += entry.missedDetection;
    }
    return {
      falseAlarm: falseAlarm / this.entries.length,
      missedDetection: missedDetection / this.entries.length,
    };
  }

  worst(): RateSummary | null {
    if (this.entries.length === 0) return null;
    return {
      falseAlarm: Math.max(...this.entries.map((entry) => entry.falseAlarm)),
      missedDetection: Math.min(...this.entries.map((entry) => entry.missedDetection)),
    };
  }

  reset(): void {
    this.entries = [];
  }

  get size(): number {
    return this.entries.length;
  }
}

