import { BinaryRateLedger } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function throwsRangeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error: unknown) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const ledger = new BinaryRateLedger();
assert(ledger.size === 0, 'new ledger is empty');
equal(ledger.average(), null, 'empty average');
equal(ledger.worst(), null, 'empty worst');

ledger.add(0, 1);
ledger.add(0.75, 0.25);
ledger.add(1, 0);
assert(ledger.size === 3, 'size counts additions');
equal(ledger.average(), { falseAlarm: (0 + 0.75 + 1) / 3, missedDetection: (1 + 0.25 + 0) / 3 }, 'arithmetic means');
equal(ledger.worst(), { falseAlarm: 1, missedDetection: 1 }, 'independent maxima');

const average1 = ledger.average();
const average2 = ledger.average();
assert(average1 !== null && average2 !== null && average1 !== average2, 'average objects are fresh');
if (average1 !== null) average1.falseAlarm = 99;
equal(ledger.average(), { falseAlarm: (0 + 0.75 + 1) / 3, missedDetection: (1 + 0.25 + 0) / 3 }, 'average mutation does not affect ledger');

const worst1 = ledger.worst();
if (worst1 !== null) worst1.missedDetection = -1;
equal(ledger.worst(), { falseAlarm: 1, missedDetection: 1 }, 'worst mutation does not affect ledger');

const invalid = [-1, 1.0000001, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY];
for (const value of invalid) {
  const sizeBefore = ledger.size;
  throwsRangeError(() => ledger.add(value, 0.5), `invalid false-alarm rate ${String(value)}`);
  assert(ledger.size === sizeBefore, 'invalid false-alarm addition is atomic');
  throwsRangeError(() => ledger.add(0.5, value), `invalid missed-detection rate ${String(value)}`);
  assert(ledger.size === sizeBefore, 'invalid missed-detection addition is atomic');
}

ledger.reset();
assert(ledger.size === 0, 'reset clears size');
equal(ledger.average(), null, 'average is empty after reset');
equal(ledger.worst(), null, 'worst is empty after reset');

